<script src="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin="anonymous"></script><script>const uptLocations=@json($mapUpts);const uptMap=L.map("upt-map").setView([-2.5,118],4);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(uptMap);const visibleMarkers=[];uptLocations.forEach(upt=>{const active=upt.status==="operasional";const marker=L.circleMarker([Number(upt.latitude),Number(upt.longitude)],{radius:8,color:active?"#147d55":"#64748b",fillColor:active?"#24a36b":"#94a3b8",fillOpacity:.9,weight:2}).addTo(uptMap);const popup=document.createElement("div");const title=document.createElement("strong");title.textContent=upt.name;const place=document.createElement("div");place.textContent=[upt.city,upt.province].filter(Boolean).join(", ");const status=document.createElement("div");status.textContent=active?"Operasional":"Non-operasional";popup.append(title,place,status);marker.bindPopup(popup);visibleMarkers.push(marker)});L.DomEvent.disableClickPropagation(document.getElementById("upt-map"));L.DomEvent.disableScrollPropagation(document.getElementById("upt-map"));document.getElementById("upt-map").addEventListener("click",event=>event.stopPropagation());setTimeout(()=>uptMap.invalidateSize(),100);</script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script>new Chart(document.getElementById('provinceChart'),{type:'bar',data:{labels:@json($provinceCounts->pluck('province')),datasets:[{label:'PTN mitra',data:@json($provinceCounts->pluck('total')),backgroundColor:'#247bb5',borderRadius:6,maxBarThickness:28}]},options:{indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}},y:{grid:{display:false}}}}});</script>
